export const pages=[{"section": "01 / PROTOTYPE STUDY", "title": "Choose a question the prototype can expose.", "lead": "This plan asks whether an invented Context Card lets a reader explain a note's source relationship and the available context change. It is a plan for inquiry, not a completed usability report.", "body": "Three tasks are crossed with three observation checkpoints. All nine cells are unrecorded. No participant identities, recruitment, session dates or results are supplied.", "subheading": "Study intention", "detail": "The intended output is a traceable record of what an actual artifact might reveal under a bounded task. It is not a success-rate target.", "question": "Which uncertainty requires observation rather than another opinion?", "records": [{"label": "Question", "prompt": "How is the note-source relationship interpreted?"}, {"label": "Scope", "prompt": "A future walkthrough of a clearly labeled paper concept."}, {"label": "Current", "prompt": "Three tasks, nine empty cells and no actual sessions."}], "image": 1, "kind": "cover", "evidenceRows": [["OBSERVATION CELL", "T01 / first-interpretation"], ["STUDY BOUNDARY", "3 tasks × 3 checkpoints; 9 unrecorded cells. No participant data."]]}, {"section": "02 / PROTOTYPE STUDY", "title": "Describe what the prototype cannot do.", "lead": "The paper concept represents a note, its source reference and alternate context panels. It has no live save, network retrieval, authentication or assistive-technology implementation.", "body": "A facilitator may substitute an authored panel after a participant describes an intended action, if that procedure is explained. The substitution is not a working response-time or reliability test.", "subheading": "Fidelity boundary", "detail": "Do not interpret a missing implementation as a participant error. Separate artifact limitations, task ambiguity and observed interaction difficulty.", "question": "Could a result be caused by the prototype's limitation?", "records": [{"label": "Represents", "prompt": "Content grouping and proposed context states."}, {"label": "Does not run", "prompt": "Saving, source retrieval or a real navigation service."}, {"label": "Procedure", "prompt": "Any panel substitution must be explained and recorded."}], "image": 1, "kind": "body", "evidenceRows": [["OBSERVATION CELL", "T01 / attempted-action"], ["STUDY BOUNDARY", "3 tasks × 3 checkpoints; 9 unrecorded cells. No participant data."]]}, {"section": "03 / PROTOTYPE STUDY", "title": "Set a scenario without teaching the cue.", "lead": "Invite a future participant to imagine returning to a note written beside an invented passage. Ask what the note refers to before pointing to the source reference or expansion action.", "body": "The scenario must not imply that a good reader will choose a particular route. Participation and recording arrangements must be established for a real study; this template grants no permission to collect data.", "subheading": "Scenario setup", "detail": "Use non-sensitive invented material. Avoid requiring personal reading history or private documents merely to make a task feel realistic.", "question": "Does the setup reveal the answer it is meant to investigate?", "records": [{"label": "Context", "prompt": "Return to an authored note after a fictional interval."}, {"label": "Material", "prompt": "Use the same invented passage and note across tasks."}, {"label": "Choice", "prompt": "Any real participation or recording needs a separate arrangement."}], "image": 2, "kind": "body", "evidenceRows": [["OBSERVATION CELL", "T01 / unresolved-question"], ["STUDY BOUNDARY", "3 tasks × 3 checkpoints; 9 unrecorded cells. No participant data."]]}, {"section": "04 / PROTOTYPE STUDY", "title": "Give each task an inspectable goal.", "lead": "T01 asks the reader to explain which passage the note concerns. T02 asks how they would reveal more context. T03 asks what they would do when context is unavailable.", "body": "Read one task at a time without naming the intended control. The script records a goal and a boundary, not a compulsory sequence or a declared success event.", "subheading": "Task scripts", "detail": "A participant may choose a route the designer did not anticipate. Record the route before deciding whether the task or artifact needs revision.", "question": "Can the goal be understood without a button name?", "records": [{"label": "T01", "prompt": "Explain which source passage the note concerns."}, {"label": "T02", "prompt": "Describe how to reveal more of the note's context."}, {"label": "T03", "prompt": "Explain the next step when context is unavailable."}], "image": 2, "kind": "body", "evidenceRows": [["OBSERVATION CELL", "T02 / first-interpretation"], ["STUDY BOUNDARY", "3 tasks × 3 checkpoints; 9 unrecorded cells. No participant data."]]}, {"section": "05 / PROTOTYPE STUDY", "title": "Separate observation from interpretation.", "lead": "The checkpoints are first interpretation, attempted action and unresolved question. A permitted record should capture what happened at each checkpoint before explaining why it may have happened.", "body": "Do not infer confusion from a pause without further context. A quiet reader, an incomplete paper panel and an unclear task can produce similar outward behavior for different reasons.", "subheading": "Observation vocabulary", "detail": "Keep quotations distinct from paraphrases and mark any facilitator intervention. The source matrix currently contains neither quotations nor observed actions.", "question": "Could another researcher distinguish the event from its explanation?", "records": [{"label": "First interpretation", "prompt": "Record the initial explanation in permitted form."}, {"label": "Attempted action", "prompt": "Record the action or described intention and any intervention."}, {"label": "Unresolved question", "prompt": "Record what remains uncertain without inventing a cause."}], "image": 3, "kind": "body", "evidenceRows": [["OBSERVATION CELL", "T02 / attempted-action"], ["STUDY BOUNDARY", "3 tasks × 3 checkpoints; 9 unrecorded cells. No participant data."]]}, {"section": "06 / PROTOTYPE STUDY", "title": "Leave unobserved cells genuinely empty.", "lead": "The matrix crosses T01, T02 and T03 with the three checkpoints, yielding nine planned cells. Each has status unrecorded and a null observation; none means a failed task.", "body": "Do not fill empty cells with plausible behavior to make the report look finished. A real session may produce no relevant observation at a checkpoint, which should be represented explicitly and separately.", "subheading": "Recording matrix", "detail": "A future record needs task, artifact version, session reference and an appropriate permission basis. This workbook contains no actual session identifiers.", "question": "Can an empty field be mistaken for a result?", "records": [{"label": "Rows", "prompt": "Three task IDs, each with three planned checkpoints."}, {"label": "Values", "prompt": "All nine observations remain null and unrecorded."}, {"label": "Meaning", "prompt": "Absence of a record is not failure, zero time or dissatisfaction."}], "image": 3, "kind": "body", "evidenceRows": [["OBSERVATION CELL", "T02 / unresolved-question"], ["STUDY BOUNDARY", "3 tasks × 3 checkpoints; 9 unrecorded cells. No participant data."]]}, {"section": "07 / PROTOTYPE STUDY", "title": "Cluster only after preserving the source records.", "lead": "Potential themes might concern source association, action wording or unavailable-context explanation. These are planning categories, not findings derived from participants.", "body": "A real synthesis should retain links to the observations it groups, preserve exceptions and distinguish artifact issues from task-script issues. Frequency alone cannot establish severity without context.", "subheading": "Issue synthesis", "detail": "Do not report that most people struggled when no sessions occurred. Avoid inventing severity ratings or completion percentages from an empty matrix.", "question": "What observation would support the proposed theme?", "records": [{"label": "Candidate theme", "prompt": "Source relationship may require a clearer explanation."}, {"label": "Evidence state", "prompt": "No observed records support or contradict that possibility."}, {"label": "Rule", "prompt": "Preserve traceable exceptions rather than forcing every note into a theme."}], "image": 4, "kind": "body", "evidenceRows": [["OBSERVATION CELL", "T03 / first-interpretation"], ["STUDY BOUNDARY", "3 tasks × 3 checkpoints; 9 unrecorded cells. No participant data."]]}, {"section": "08 / PROTOTYPE STUDY", "title": "Connect a revision to a specific uncertainty.", "lead": "If a future record suggests the source relation is unclear, a revised panel could change the reference placement while keeping wording constant. That is a proposed next comparison, not a validated fix.", "body": "Record the version difference and the question it addresses. Changing task wording, content and layout at once can obscure what explains an observed difference.", "subheading": "Iteration plan", "detail": "A cleaner drawing is not evidence of improved usability. Any claim about improvement needs an appropriate comparison and a transparent boundary.", "question": "What would a follow-up task distinguish?", "records": [{"label": "Hypothetical change", "prompt": "Adjust reference placement without changing note wording."}, {"label": "Control", "prompt": "Retain the same passage and task goal."}, {"label": "Status", "prompt": "No actual issue, revision result or measured improvement exists."}], "image": 4, "kind": "body", "evidenceRows": [["OBSERVATION CELL", "T03 / attempted-action"], ["STUDY BOUNDARY", "3 tasks × 3 checkpoints; 9 unrecorded cells. No participant data."]]}, {"section": "09 / PROTOTYPE STUDY", "title": "Make the limitations part of the result format.", "lead": "Even a completed small walkthrough would be bounded by its artifact, tasks, participants and setting. This plan has additional limits because it has not been executed at all.", "body": "Paper panels cannot establish persistence, live latency, keyboard operation or assistive-technology behavior. No claim about a population, business outcome or accessibility conformance follows from this plan.", "subheading": "Study limits", "detail": "Keep missing evidence visible in the handoff. A reader should not have to infer that a polished matrix is empty of participant data.", "question": "Which conclusion is outside the method's reach?", "records": [{"label": "Not measured", "prompt": "Task completion, time, error rate or satisfaction."}, {"label": "Not tested", "prompt": "Live behavior, keyboard access or assistive technology."}, {"label": "Not inferred", "prompt": "Population preference, adoption or business value."}], "image": 5, "kind": "body", "evidenceRows": [["OBSERVATION CELL", "T03 / unresolved-question"], ["STUDY BOUNDARY", "3 tasks × 3 checkpoints; 9 unrecorded cells. No participant data."]]}, {"section": "10 / PROTOTYPE STUDY", "title": "Prepare the next study without announcing findings.", "lead": "The next step is to review the task script and the paper panels for misleading cues, then establish a real participation and recording process if the study proceeds.", "body": "Keep the unrecorded matrix as a planning fixture. Any future data must be versioned and sourced rather than silently overwriting null cells while retaining this document's claim that no sessions occurred.", "subheading": "Research handoff", "detail": "Share the question, artifact limits, task goals and observation vocabulary together. A successor should know both what to collect and what not to conclude.", "question": "What is required before any cell becomes evidence?", "records": [{"label": "Prepare", "prompt": "Review task wording and clearly label the paper concept."}, {"label": "Arrange", "prompt": "Establish actual participation, recording and data-handling terms."}, {"label": "Preserve", "prompt": "Version the fixture before adding real observations."}], "image": 5, "kind": "appendix", "evidenceRows": [["OBSERVATION CELL", "T01 / first-interpretation"], ["STUDY BOUNDARY", "3 tasks × 3 checkpoints; 9 unrecorded cells. No participant data."]]}];
